<?php require 'config.php'; $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$sid=trim($_POST['sid']??'');$password=$_POST['password']??'';$q=$pdo->prepare('SELECT * FROM users WHERE student_id=?');$q->execute([$sid]);$u=$q->fetch();if($u&&password_verify($password,$u['password_hash'])){session_regenerate_id(true);$_SESSION['user']=['id'=>$u['id'],'student_id'=>$u['student_id'],'name'=>$u['full_name'],'email'=>$u['email'],'department'=>$u['department'],'semester'=>$u['semester'],'role'=>$u['role']];header('Location: dashboard.php');exit;} $error='Invalid student ID or password.';} ?>
